const app=document.querySelector('#app');let timer=null;let position=0;let currentTheme='minimal';
const designs={minimal:{label:'01 / MINIMAL'},field:{label:'02 / FIELD MANUAL'},signal:{label:'03 / SIGNAL'}};
function terrain(units=true){return `<svg viewBox="0 0 600 440" role="img" aria-label="Illustrative tactical terrain map"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="currentColor" opacity=".10"/></pattern></defs><rect width="600" height="440" fill="url(#grid)"/><g fill="none" stroke="currentColor" opacity=".18">${Array.from({length:8},(_,i)=>`<path d="M${-120+i*24} 440 Q${70+i*25} 300 ${10+i*28} 170 T${280+i*25} -40"/>`).join('')}<path d="M0 320Q180 240 230 290T600 200" stroke-width="25" opacity=".35"/><path d="M0 320Q180 240 230 290T600 200" stroke-width="2"/></g><g fill="currentColor" opacity=".13"><rect x="345" y="130" width="32" height="45" transform="rotate(20 345 130)"/><rect x="395" y="156" width="45" height="24"/><rect x="370" y="205" width="28" height="20"/></g><g id="routeLayer"><path d="M100 355L210 305L290 230L410 150" stroke="var(--accent)" stroke-width="2" stroke-dasharray="7 7" fill="none"/><circle cx="410" cy="150" r="40" fill="none" stroke="var(--accent)"/><path d="M410 135v30m-15-15h30" stroke="var(--accent)"/></g>${units?'<g id="unitLayer"><g id="squad" transform="translate(210 305)"><circle r="20" fill="var(--accent)" opacity=".15"/><circle r="6" fill="var(--accent)"/><text x="17" y="-13" font-size="11" fill="var(--ink)" font-family="monospace">ALPHA</text></g><g transform="translate(270 330)"><path d="M0-6L7 6H-7Z" fill="var(--accent)"/><text x="14" y="5" font-size="10" fill="var(--ink)" font-family="monospace">BRAVO</text></g></g>':''}</svg>`}
function link(page,text,cls=''){return `<a class="${cls}" href="#${currentTheme}/${page}">${text}</a>`}

function navigation(page){
 const links=currentTheme==='minimal'?[['media','Media'],['operations','Sessions']]:currentTheme==='field'?[['home','Community'],['media','Media'],['operations','Sessions']]:[['home','Discover'],['operations','Rendezvous'],['playback','Rewind'],['join','Connect']];
 return `<nav aria-label="Main navigation">${links.map(([route,label])=>`<a href="#${currentTheme}/${route}" ${page===route?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
}
function shell(page,content){
 const source='<a href="https://globalconflicts.net/" target="_blank" rel="noopener">Community site ↗</a>';
 if(currentTheme==='minimal')return `<div class="minimal-shell"><header class="minimal-header">${link('home','Global Conflicts','minimal-brand')}${navigation(page)}</header><main>${content}</main></div>`;
 if(currentTheme==='field')return `<div class="field-shell"><header class="quiet-header">${link('home','Global Conflicts','quiet-brand')}<button class="menu-trigger" id="openMenu" popovertarget="siteMenu" aria-expanded="false" aria-controls="siteMenu">Explore pages <span aria-hidden="true">☰</span></button></header><div id="siteMenu" class="field-menu" popover="auto"><div class="menu-top"><span>Global Conflicts</span><button id="closeMenu" aria-label="Close menu">Close ×</button></div>${navigation(page)}${link('playback','Playback','menu-extra')}<a class="menu-discord" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join our Discord ↗</a><div class="menu-concepts"><span>Other prototypes</span><a href="#minimal/home">01 Minimal</a><a href="#signal/home">03 Signal</a></div></div><main>${content}</main><footer><span>Global Conflicts</span><a href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Discord ↗</a><a href="#minimal/home">Compare prototypes →</a></footer></div>`;
 return `<div class="signal-shell"><header class="signal-header">${link('home','<span class="signal-glyph">✳</span><span>GLOBAL<br>CONFLICTS</span>','signal-brand')}<span class="signal-frequency">COMMUNITY FREQUENCY<br>ARMA REFORGER</span><span class="signal-index">GC—003</span></header><main>${content}</main><div class="signal-dock">${navigation(page)}<a class="dock-source" href="https://globalconflicts.net/" target="_blank" rel="noopener" aria-label="Original Global Conflicts site">↗</a></div><footer><span>Signal / an experimental community interface</span><span>Design concept · ${source}</span></footer></div>`;
}
function render(){window.scrollTo(0,0);clearInterval(timer);timer=null;const parts=location.hash.slice(1).split('/');currentTheme=designs[parts[0]]?parts[0]:'minimal';const page=['home','operations','playback','join','media'].includes(parts[1])?parts[1]:'home';document.body.className=currentTheme+' page-'+page;document.querySelectorAll('[data-theme]').forEach(a=>{a.classList.toggle('active',a.dataset.theme===currentTheme);a.href='#'+a.dataset.theme+'/'+page});app.innerHTML=shell(page,page==='home'?home():page==='media'?media():page==='playback'?playback():page==='operations'?operations():join());if(currentTheme==='field')wireField();if(page==='playback')wirePlayer();if(currentTheme==='signal'&&page==='home')wireSignal();document.title=`${designs[currentTheme].label.slice(5)} — Global Conflicts`;}
function home(){
 if(currentTheme==='minimal')return `<section class="minimal-intro"><h1>One life.<br>Play it together.</h1><p class="minimal-description">Global Conflicts. A one-life Arma Reforger milsim community.</p><div class="minimal-session"><p>Saturday & Sunday <span>·</span> 19:00 UTC</p><small>Join Discord for server setup, session updates, and your squad.</small></div><div class="minimal-actions"><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join our Discord ↗</a>${link('media','Watch how to play →','minimal-watch')}</div></section>`;
 if(currentTheme==='field')return `<section class="field-opening"><div class="opening-copy"><h1>One life.<br><span>Arma Reforger.</span></h1><p>A milsim community built on teamwork.</p><p class="opening-time">Saturday & Sunday · 19:00 UTC</p><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join our Discord ↗</a></div><figure class="opening-media"><img src="squad.jpg" alt="Two soldiers advancing together beside a building, from the Global Conflicts community archive" fetchpriority="high"></figure><button class="scroll-invitation" id="exploreBelow">See how we play <span aria-hidden="true">↓</span></button></section><section id="howWePlay" class="field-story"><div class="story-copy"><h2>How we play.</h2></div><div class="story-video" id="introPlayer"><button id="playIntro" aria-label="Play the Global Conflicts introduction"><img src="intro-thumbnail.jpg" alt="Global Conflicts guide to joining and playing Arma Reforger"><span class="story-play" aria-hidden="true">▶</span></button><a href="https://www.youtube.com/watch?v=_SW1tEkcfRU" target="_blank" rel="noopener">Watch on YouTube ↗</a></div></section><section class="field-join-section"><div><h2>Your next<br>session starts here.</h2><p class="large-session-time">Saturday & Sunday<br><span>19:00 UTC</span></p></div><div class="join-copy"><p>Discord is where we meet, plan, and play. Get your server details and mods, ask questions, and find your squad.</p><p>Bring a working microphone and a mature attitude. We’ll help you get started.</p><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Meet us on Discord ↗</a></div></section><section class="field-more"><img src="community.jpg" alt="A scene from the Global Conflicts community archive"><div><h2>There’s more to explore.</h2><p>Community videos, photos, and stories from past operations.</p>${link('media','Explore our media →','text-link')}</div></section>`;
 return `<section class="transmission"><div class="signal-topline"><span>A SHARED WORLD. A SHARED OBJECTIVE.</span><span>INTERACTIVE TRANSMISSION / 003</span></div><h1>NO ONE<br><span>PLAYS ALONE.</span></h1><div class="signal-world">${globe()}<div class="world-axis axis-a"></div><div class="world-axis axis-b"></div><button class="beacon beacon-one selected" data-channel="who" aria-label="Who we are" aria-pressed="true"><span></span>01 / WHO</button><button class="beacon beacon-two" data-channel="when" aria-label="When we play" aria-pressed="false"><span></span>02 / WHEN</button><button class="beacon beacon-three" data-channel="how" aria-label="How to join" aria-pressed="false"><span></span>03 / HOW</button><span class="world-caption">SELECT A SIGNAL TO EXPLORE</span></div><div class="transmission-card" aria-live="polite"><span id="signalKicker">01 / PEOPLE, NOT RANKS</span><h2 id="signalTitle">Your people.<br>Your next squad.</h2><p id="signalText">Global Conflicts. Tactical Arma Reforger, built around teamwork.</p><a id="signalAction" href="#signal/join">Find your squad ↗</a></div><a class="connect-disc" href="#signal/join"><span>JOIN THE<br>COMMUNITY</span><b>↗</b></a><div class="signal-time"><span>WEEKEND FREQUENCY</span><strong>SAT / SUN<br>19:00 UTC</strong><small>Session updates and setup<br>on our Discord</small></div><a class="rewind-link" href="#signal/playback"><span>◀◀</span><div>THE MISSION DOESN’T END HERE.<br><b>Enter the playback lab ↗</b></div></a></section>`;
}
function wireField(){
 const panel=document.querySelector('#siteMenu'),trigger=document.querySelector('#openMenu');
 let openTimer,closeTimer,pinned=false;
 const isOpen=()=>panel.matches(':popover-open');
 const closeMenu=()=>{clearTimeout(openTimer);clearTimeout(closeTimer);pinned=false;if(isOpen())panel.hidePopover()};
 const showMenu=()=>{if(!isOpen())panel.showPopover()};
 const canHover=()=>window.matchMedia('(hover: hover) and (pointer: fine)').matches;
 const scheduleClose=()=>{clearTimeout(openTimer);if(!pinned)closeTimer=setTimeout(closeMenu,280)};
 trigger.onclick=event=>{event.preventDefault();clearTimeout(openTimer);clearTimeout(closeTimer);if(isOpen()&&pinned){closeMenu()}else{pinned=true;showMenu()}};
 trigger.addEventListener('pointerenter',event=>{if(event.pointerType==='mouse'&&canHover()){clearTimeout(closeTimer);openTimer=setTimeout(showMenu,160)}});
 trigger.addEventListener('pointerleave',event=>{if(event.pointerType==='mouse'&&canHover())scheduleClose()});
 panel.addEventListener('pointerenter',()=>clearTimeout(closeTimer));
 panel.addEventListener('pointerleave',event=>{if(event.pointerType==='mouse'&&canHover())scheduleClose()});
 panel.addEventListener('focusin',()=>{pinned=true;clearTimeout(closeTimer)});
 panel.addEventListener('toggle',()=>{trigger.setAttribute('aria-expanded',String(isOpen()));if(!isOpen()){pinned=false;clearTimeout(openTimer);clearTimeout(closeTimer)}});
 document.querySelector('#closeMenu').onclick=()=>{closeMenu();trigger.focus()};
 panel.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{closeMenu();if(a.getAttribute('href')===location.hash)window.scrollTo(0,0)}));
 document.querySelector('#exploreBelow')?.addEventListener('click',()=>document.querySelector('#howWePlay').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 document.querySelector('#playIntro')?.addEventListener('click',()=>{document.querySelector('#introPlayer').innerHTML='<div class="video-embed"><iframe src="https://www.youtube-nocookie.com/embed/_SW1tEkcfRU?autoplay=1" title="Global Conflicts Guide: How to Join and Play Arma Reforger With Us" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><a href="https://www.youtube.com/watch?v=_SW1tEkcfRU" target="_blank" rel="noopener">Watch on YouTube ↗</a>'})
}
function globe(){return `<svg viewBox="0 0 600 600" aria-label="Illustrative connected globe" role="img"><defs><clipPath id="sphere"><circle cx="300" cy="300" r="236"/></clipPath><radialGradient id="sphereGlow"><stop stop-color="#5284ff" stop-opacity=".3"/><stop offset="1" stop-color="#081c6d" stop-opacity=".1"/></radialGradient><pattern id="dots" width="9" height="9" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.2" fill="#e6f0ff"/></pattern></defs><circle cx="300" cy="300" r="236" fill="url(#sphereGlow)" stroke="#b5cbff" stroke-opacity=".55"/><g clip-path="url(#sphere)" fill="none" stroke="#a7c3ff" stroke-opacity=".25">${[65,130,195,236].map(r=>`<ellipse cx="300" cy="300" rx="${r}" ry="236"/>`).join('')}${[150,220,300,380,450].map(y=>`<ellipse cx="300" cy="${y}" rx="236" ry="${Math.max(18,80-Math.abs(300-y)/3)}"/>`).join('')}<path d="M50 300H550M300 50V550"/></g><g clip-path="url(#sphere)" fill="url(#dots)" stroke="#b2c9ff" stroke-opacity=".6" stroke-width=".5"><path d="M92 166L143 126L205 122L246 149L233 182L266 216L239 250L207 249L190 281L163 271L144 233L110 219Z"/><path d="M204 293L245 286L286 317L270 353L268 389L242 426L225 469L208 444L216 397L198 358L184 321Z"/><path d="M308 128L354 114L373 132L412 122L456 151L508 174L534 217L513 249L462 248L449 284L419 267L397 234L367 240L350 216L319 218L306 188L328 167Z"/><path d="M326 243L368 231L399 268L390 310L365 349L344 380L326 346L303 310L305 269Z"/><path d="M448 364L478 348L507 364L511 397L472 410L439 391Z"/></g><ellipse cx="300" cy="300" rx="290" ry="86" transform="rotate(-25 300 300)" fill="none" stroke="#f4ff90" stroke-width="1.5"/><circle cx="90" cy="440" r="5" fill="#f4ff90"/><circle cx="473" cy="135" r="4" fill="#f4ff90"/></svg>`}
function wireSignal(){const channels={who:['01 / PEOPLE, NOT RANKS','Your people.<br>Your next squad.','Global Conflicts. Tactical Arma Reforger, built around teamwork.','Find your squad ↗','join'],when:['02 / THE RENDEZVOUS','Same time.<br>Shared objective.','Saturday & Sunday, 19:00 UTC. Join Discord for the latest session details.','Explore sessions ↗','operations'],how:['03 / OPEN CHANNEL','Mic on.<br>Come as you are.','Bring a working microphone and a mature attitude. Meet GC and confirm your server setup.','Get connected ↗','join']};document.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{const c=channels[b.dataset.channel];document.querySelector('#signalKicker').textContent=c[0];document.querySelector('#signalTitle').innerHTML=c[1];document.querySelector('#signalText').textContent=c[2];document.querySelector('#signalAction').textContent=c[3];document.querySelector('#signalAction').href='#signal/'+c[4];document.querySelectorAll('[data-channel]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',el===b?'true':'false')})})}
function operations(){if(currentTheme==='minimal')return `<section class="minimal-page"><h1>Sessions</h1><p>Make time for your squad.</p><dl class="minimal-times"><div><dt>Saturday</dt><dd>19:00 UTC</dd></div><div><dt>Sunday</dt><dd>19:00 UTC</dd></div></dl><p class="minimal-note">Join Discord for server details, required mods, and session updates.</p>${link('join','How to join','btn')}</section>`;const rows=['Saturday','Sunday'].map((day,i)=>`<article><span class="session-number">0${i+1}</span><div><span class="eyebrow">Weekly sessions</span><h2>${day}</h2></div><div class="session-time">19:00 <span>UTC</span></div>${link('join','Joining instructions ↗','text-link')}</article>`).join('');return `<div class="page-heading"><span class="eyebrow">${currentTheme==='field'?'Deployment schedule':currentTheme==='signal'?'02 / Rendezvous':'Sessions'}</span><h1>${currentTheme==='field'?'Weekend sessions.':currentTheme==='signal'?'Meet on the<br>same frequency.':'Your weekend,<br>with the squad.'}</h1><p>One-life Arma Reforger milsim, every Saturday and Sunday at 19:00 UTC. Join Discord for setup and session updates.</p></div><section class="schedule">${rows}</section><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join Discord for session details ↗</a>`}
function join(){return `<section class="${currentTheme==='minimal'?'minimal-page':'page-heading join-focused'}"><span class="eyebrow">YOUR FIRST SESSION</span><h1>Join the squad.</h1><p>A working microphone. A mature attitude. One shared objective.</p><ol class="minimal-joining"><li>Join Discord and meet the community.</li><li>Get the Reforger server details and required mods.</li><li>Be ready Saturday or Sunday at 19:00 UTC.</li></ol><a class="btn" href="https://discord.globalconflicts.net" target="_blank" rel="noopener">Join our Discord ↗</a><p>${link('media','Watch the joining guide →','text-link')}</p></section>`}
function media(){return `<section class="media-page"><div class="media-heading"><span class="eyebrow">GET TO KNOW GLOBAL CONFLICTS</span><h1>See how we play.</h1><p>One-life Arma Reforger milsim, from your first connection to the mission briefing.</p></div><div class="media-feature"><div class="video-embed"><iframe src="https://www.youtube-nocookie.com/embed/_SW1tEkcfRU" title="Global Conflicts Guide: How to Join and Play Arma Reforger With Us" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><div class="media-feature-caption"><h2>How to join & play</h2><a href="https://www.youtube.com/watch?v=_SW1tEkcfRU" target="_blank" rel="noopener">Watch on YouTube ↗</a></div></div><div class="media-explore"><article class="media-archive"><img src="community.jpg" alt="Vehicles on a forest road from the Global Conflicts community archive"><div><span class="eyebrow">FROM THE COMMUNITY ARCHIVE</span><h2>More from the field.</h2><a href="https://www.youtube.com/@GlobalConflicts_" target="_blank" rel="noopener" class="text-link">Explore the GC video channel ↗</a></div></article><section class="media-links"><div><h2>Next session</h2><p>Saturday & Sunday · 19:00 UTC</p>${link('operations','Session details →','text-link')}</div><div><h2>Past operations & community</h2><p>Photos, event updates, and after-action discussions live on Discord.</p><a href="https://discord.globalconflicts.net" target="_blank" rel="noopener" class="text-link">Explore our Discord ↗</a></div><div><h2>Playback lab</h2><p>Try a simulated briefing with chapters and a tactical timeline.</p>${link('playback','Open the playback demo →','text-link')}</div></section></div></section>`}
function playback(){return `<div class="page-heading player-heading"><div><span class="eyebrow">${currentTheme==='field'?'After action / briefing room':currentTheme==='signal'?'Rewind / transmission archive':'Briefing player'} · SIMULATED DATA</span><h1>${currentTheme==='field'?'Operation Pine':currentTheme==='signal'?'Rewind the operation.':'Operation Pine'}</h1></div><p>Fictional scenario · 2 min demo</p></div><section class="workspace" aria-label="Briefing player"><aside class="sidebar"><div class="eyebrow">Chapters</div><button data-time="0">01 &nbsp; Situation</button><button data-time="35">02 &nbsp; Approach</button><button data-time="70">03 &nbsp; Objective</button><button data-time="100">04 &nbsp; Debrief</button></aside><div class="map">${terrain()}<span class="map-caption">ILLUSTRATIVE TERRAIN / NOT GAME DATA</span></div><aside class="intel"><div><span class="eyebrow">Briefing notes</span><h3 id="chapterTitle">Situation</h3><p id="chapterNote"></p></div><div><span class="eyebrow">Map layers</span><label><input type="checkbox" checked id="units"> Squad positions</label><label><input type="checkbox" checked id="routes"> Planned route</label></div></aside></section><div class="timeline"><button id="play" aria-label="Play simulated briefing">▶ Play</button><output id="time">00:00 / 02:00</output><input aria-label="Playback position" id="scrub" type="range" min="0" max="120" value="0"><select id="speed" aria-label="Playback speed"><option value="1">1× speed</option><option value="2">2× speed</option><option value="4">4× speed</option></select><button id="reset">↺ Reset</button></div><p class="demo-note">Interactive concept with simulated data. Live recordings and game integration are future work.</p>`}
function wirePlayer(){position=0;const notes=['Alpha and Bravo assemble southwest of the objective. Review the planned approach.','Alpha advances along the marked route. Bravo holds the southern approach.','Alpha reaches the objective area. Coordinate the final approach with Bravo.','Review squad movement and timing. Use the timeline to revisit key moments.'];function update(){document.querySelector('#scrub').value=position;document.querySelector('#time').textContent=`${String(Math.floor(position/60)).padStart(2,'0')}:${String(Math.floor(position%60)).padStart(2,'0')} / 02:00`;let idx=position<35?0:position<70?1:position<100?2:3;document.querySelector('#chapterTitle').textContent=['Situation','Approach','Objective','Debrief'][idx];document.querySelector('#chapterNote').textContent=notes[idx];document.querySelectorAll('[data-time]').forEach((b,i)=>b.classList.toggle('selected',i===idx));document.querySelector('#squad').setAttribute('transform',`translate(${100+position*2.58} ${355-position*1.7})`)}function stop(){clearInterval(timer);timer=null;document.querySelector('#play').textContent='▶ Play';document.querySelector('#play').setAttribute('aria-label','Play simulated briefing')}document.querySelector('#play').onclick=()=>{if(timer){stop();return}if(position>=120)position=0;document.querySelector('#play').textContent='Ⅱ Pause';document.querySelector('#play').setAttribute('aria-label','Pause simulated briefing');timer=setInterval(()=>{position=Math.min(120,position+.25*Number(document.querySelector('#speed').value));update();if(position>=120)stop()},250)};document.querySelector('#scrub').oninput=e=>{position=Number(e.target.value);update()};document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{position=Number(b.dataset.time);update()});document.querySelector('#reset').onclick=()=>{stop();position=0;update()};document.querySelector('#units').onchange=e=>document.querySelector('#unitLayer').style.display=e.target.checked?'':'none';document.querySelector('#routes').onchange=e=>document.querySelector('#routeLayer').style.display=e.target.checked?'':'none';update()}
window.addEventListener('hashchange',render);render();

